const fs=require('node:fs'),c=require('node:crypto'),cp=require('node:child_process'),ref=JSON.parse(fs.readFileSync('qa401-reference.json')),marker=JSON.parse(fs.readFileSync('qa401-marker.json')),phase=process.argv[2],sha=b=>c.createHash('sha256').update(b).digest('hex');
