const installed=()=>{try{return require('express/package.json').version}catch(e){if(e.code==='MODULE_NOT_FOUND')return null;throw e}},snapshot={marker,node:process.version,yarn:cp.execFileSync('yarn',['--version'],{encoding:'utf8'}).trim(),files,node_modules_present:fs.existsSync('node_modules'),express_version:installed(),skip_present:Object.hasOwn(process.env,'SKIP_INSTALL_DEPS'),skip:process.env.SKIP_INSTALL_DEPS??null};
if(phase==='before'){fs.writeFileSync('qa401-before.json',JSON.stringify(snapshot));console.log('QA401_BEFORE '+JSON.stringify(snapshot));process.exit(0)}
const express=require('express'),app=express();if(typeof app!=='function'||snapshot.express_version!=='4.18.2')throw Error('locked dependency differs');const index=Buffer.from('<!doctype html><title>qa401</title><p>'+marker+' Express '+snapshot.express_version+'</p>\n'),result={...snapshot,before:JSON.parse(fs.readFileSync('qa401-before.json')),index:{bytes:index.length,sha256:sha(index)},instantiated_express:true};fs.mkdirSync('_site',{recursive:true});fs.writeFileSync('_site/index.html',index);fs.writeFileSync('_site/qa401-evidence.json',JSON.stringify(result));console.log('QA401_AFTER '+JSON.stringify(result));
